; DAPP.S - APPLICATIONS PAGE RENDERER

DAPPRENDER:
    JSR CLEARSCREEN
    JSR DRAWFRAME
    
    LDA #5
    STA $72
    LDA #2
    STA $77
    LDX #<APPTITLESTR
    LDY #>APPTITLESTR
    JSR PRINTAT
    
    LDA #7
    STA $72
    LDX #<APPLABEL1
    LDY #>APPLABEL1
    JSR PRINTAT
    
    LDA #9
    STA $72
    LDX #<APPLABEL2
    LDY #>APPLABEL2
    JSR PRINTAT
    RTS
